1	import { randomUUID } from 'node:crypto';
2	import type { DatabaseSync } from 'node:sqlite';
3	import { transaction } from './db.ts';
4	
5	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
6	
7	/** The public job shape returned by every endpoint that returns a job. */
8	export interface Job {
9	  id: string;
10	  status: JobStatus;
11	  input: string;
12	  steps: number;
13	  failAttempts: number;
14	  attempts: number;
15	  progress: { completed: number; total: number };
16	  result: { output: string } | null;
17	  error: string | null;
18	  createdAt: string;
19	  updatedAt: string;
20	}
21	
22	interface JobRow {
23	  seq: number;
24	  id: string;
25	  status: JobStatus;
26	  input: string;
27	  steps: number;
28	  fail_attempts: number;
29	  attempts: number;
30	  completed: number;
31	  result_output: string | null;
32	  error: string | null;
33	  idempotency_key: string | null;
34	  next_run_at: number;
35	  created_at: string;
36	  updated_at: string;
37	}
38	
39	export interface ClaimedJob {
40	  id: string;
41	  /** 1-based number of the attempt that is starting. */
42	  attempt: number;
43	  input: string;
44	  steps: number;
45	  failAttempts: number;
46	}
47	
48	type Param = string | number | null;
49	
50	function one<T>(db: DatabaseSync, sql: string, ...params: Param[]): T | undefined {
51	  return db.prepare(sql).get(...params) as unknown as T | undefined;
52	}
53	
54	function toJob(row: JobRow): Job {
55	  return {
56	    id: row.id,
57	    status: row.status,
58	    input: row.input,
59	    steps: row.steps,
60	    failAttempts: row.fail_attempts,
61	    attempts: row.attempts,
62	    progress: { completed: row.completed, total: row.steps },
63	    result: row.result_output === null ? null : { output: row.result_output },
64	    error: row.error,
65	    createdAt: row.created_at,
66	    updatedAt: row.updated_at,
67	  };
68	}
69	
70	function getRow(db: DatabaseSync, id: string): JobRow | undefined {
71	  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
72	}
73	
74	export function getJob(db: DatabaseSync, id: string): Job | undefined {
75	  const row = getRow(db, id);
76	  return row && toJob(row);
77	}
78	
79	/** All jobs, newest first. */
80	export function listJobs(db: DatabaseSync): Job[] {
81	  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
82	}
83	
84	export type CreateResult =
85	  | { kind: 'created'; job: Job }
86	  | { kind: 'replayed'; job: Job }
87	  | { kind: 'conflict' };
88	
89	/**
90	 * Creates a job. With an idempotency key, an earlier job that used the same key is returned when
91	 * the payload matches, and a conflict is reported when it does not. The lookup and the insert run
92	 * in one write transaction, and the UNIQUE constraint on idempotency_key backs it up.
93	 */
94	export function createJob(
95	  db: DatabaseSync,
96	  s: { input: string; steps: number; failAttempts: number; idempotencyKey?: string },
97	): CreateResult {
98	  return transaction(db, (): CreateResult => {
99	    if (s.idempotencyKey !== undefined) {
100	      const existing = one<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', s.idempotencyKey);
101	      if (existing) {
102	        const same = existing.input === s.input && existing.steps === s.steps && existing.fail_attempts === s.failAttempts;
103	        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
104	      }
105	    }
106	    const id = randomUUID();
107	    const now = new Date().toISOString();
108	    db.prepare(
109	      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
110	       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
111	    ).run(id, s.input, s.steps, s.failAttempts, s.idempotencyKey ?? null, now, now);
112	    const row = getRow(db, id);
113	    if (!row) throw new Error(`job ${id} missing after insert`);
114	    return { kind: 'created', job: toJob(row) };
115	  });
116	}
117	
118	/**
119	 * Claims the oldest queued job whose retry delay has passed, marking it running and starting a new
120	 * attempt. Returns undefined when nothing is ready.
121	 */
122	export function claimNextJob(db: DatabaseSync, now: number = Date.now()): ClaimedJob | undefined {
123	  return transaction(db, (): ClaimedJob | undefined => {
124	    const row = one<JobRow>(
125	      db,
126	      "SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1",
127	      now,
128	    );
129	    if (!row) return undefined;
130	    db.prepare(
131	      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
132	    ).run(new Date().toISOString(), row.id);
133	    return {
134	      id: row.id,
135	      attempt: row.attempts + 1,
136	      input: row.input,
137	      steps: row.steps,
138	      failAttempts: row.fail_attempts,
139	    };
140	  });
141	}
142	
143	/**
144	 * Called at worker startup and on graceful shutdown. A job left `running` was interrupted before
145	 * its attempt finished, so the interrupted attempt is rolled back and the job is queued to run that
146	 * same attempt again. This keeps `attempts` within the 3-attempt budget.
147	 */
148	export function recoverInterruptedJobs(db: DatabaseSync): number {
149	  const result = db
150	    .prepare(
