import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

export interface ClaimedJob {
  id: string;
  /** 1-based number of the attempt that is starting. */
  attempt: number;
  input: string;
  steps: number;
  failAttempts: number;
}

type Param = string | number | null;

function one<T>(db: DatabaseSync, sql: string, ...params: Param[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.result_output === null ? null : { output: row.result_output },
    error: row.error,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function getRow(db: DatabaseSync, id: string): JobRow | undefined {
  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = getRow(db, id);
  return row && toJob(row);
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
}

export type CreateResult =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

/**
 * Creates a job. With an idempotency key, an earlier job that used the same key is returned when
 * the payload matches, and a conflict is reported when it does not. The lookup and the insert run
 * in one write transaction, and the UNIQUE constraint on idempotency_key backs it up.
 */
export function createJob(
  db: DatabaseSync,
  s: { input: string; steps: number; failAttempts: number; idempotencyKey?: string },
): CreateResult {
  return transaction(db, (): CreateResult => {
    if (s.idempotencyKey !== undefined) {
      const existing = one<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', s.idempotencyKey);
      if (existing) {
        const same = existing.input === s.input && existing.steps === s.steps && existing.fail_attempts === s.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, s.input, s.steps, s.failAttempts, s.idempotencyKey ?? null, now, now);
    const row = getRow(db, id);
    if (!row) throw new Error(`job ${id} missing after insert`);
    return { kind: 'created', job: toJob(row) };
  });
}

/**
 * Claims the oldest queued job whose retry delay has passed, marking it running and starting a new
 * attempt. Returns undefined when nothing is ready.
 */
export function claimNextJob(db: DatabaseSync, now: number = Date.now()): ClaimedJob | undefined {
  return transaction(db, (): ClaimedJob | undefined => {
    const row = one<JobRow>(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1",
      now,
    );
    if (!row) return undefined;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
    ).run(new Date().toISOString(), row.id);
    return {
      id: row.id,
      attempt: row.attempts + 1,
      input: row.input,
      steps: row.steps,
      failAttempts: row.fail_attempts,
    };
  });
}

/**
 * Called at worker startup and on graceful shutdown. A job left `running` was interrupted before
 * its attempt finished, so the interrupted attempt is rolled back and the job is queued to run that
 * same attempt again. This keeps `attempts` within the 3-attempt budget.
 */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  const result = db
    .prepare(
      "UPDATE jobs SET status = 'queued', attempts = attempts - 1, completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'",
    )
    .run(new Date().toISOString());
  return Number(result.changes);
}

export function recordProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
  ).run(output, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ?",
  ).run(error, new Date().toISOString(), id);
}

export function requeueForRetry(db: DatabaseSync, id: string, runAt: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', next_run_at = ?, updated_at = ? WHERE id = ?").run(
    runAt,
    new Date().toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, now: number = Date.now()): void {
  db.prepare(
    'INSERT INTO heartbeat (id, ts) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET ts = excluded.ts',
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM heartbeat').run();
}

/** True when the worker wrote a heartbeat within the last `maxAgeMs` milliseconds. */
export function isWorkerUp(db: DatabaseSync, maxAgeMs = 3000, now: number = Date.now()): boolean {
  const row = one<{ ts: number }>(db, 'SELECT ts FROM heartbeat WHERE id = 1');
  return row !== undefined && now - row.ts <= maxAgeMs;
}

