export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

function isJsonContentType(value: string | undefined): boolean {
  return value !== undefined && /^application\/json\s*(;|$)/i.test(value.trim());
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/**
 * Validates a job submission. `rawBody` is the request body text, or null when it was too large to
 * read. Every problem is reported, one entry per offending field.
 */
export function parseSubmission(
  contentType: string | undefined,
  rawBody: string | null,
  idempotencyHeader: string | string[] | undefined,
): ParseResult {
  const fields: FieldError[] = [];

  let idempotencyKey: string | undefined;
  if (idempotencyHeader !== undefined) {
    const key = Array.isArray(idempotencyHeader) ? idempotencyHeader.join(', ') : idempotencyHeader;
    if (IDEMPOTENCY_KEY.test(key)) idempotencyKey = key;
    else fields.push({ field: 'Idempotency-Key', message: 'must be 1-128 characters: letters, digits, "_" or "-"' });
  }

  let body: Record<string, unknown> | undefined;
  if (!isJsonContentType(contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (rawBody === null) {
    fields.push({ field: 'body', message: 'request body is too large' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      fields.push({ field: 'body', message: 'request body is not valid JSON' });
      parsed = undefined;
    }
    if (parsed !== undefined) {
      if (isPlainObject(parsed)) body = parsed;
      else fields.push({ field: 'body', message: 'request body must be a JSON object' });
    }
  }

  if (body === undefined) return { ok: false, fields };

  for (const key of Object.keys(body)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (body.input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof body.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (body.input.length < 1 || body.input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1-${MAX_INPUT_LENGTH} characters` });
  } else if (body.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = body.input;
  }

  const steps = integerField(body, 'steps', 1, 20, DEFAULT_STEPS, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts, idempotencyKey } };
}

function integerField(
  body: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number {
  const v = body[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  if (v < min || v > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

